targets.query:
// Raw rpm/speed ratio = the signal gear is derived from (one point per sample, no averaging).
// Only while moving (speed >= 8) and pulling (rpm >= 800); below that the ratio is meaningless.
// Dashed threshold lines mark the six gear centroids. See infra/vps/grafana/README.md.
from(bucket: "telemetry")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "telemetry" and (r._field == "rpm" or r._field == "speed"))
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> filter(fn: (r) => r.speed >= 8.0 and r.rpm >= 800.0)
  |> map(fn: (r) => ({ _time: r._time, _field: "ratio", _value: r.rpm / r.speed }))
  |> aggregateWindow(every: v.windowPeriod, fn: last, createEmpty: false)

// Gear DERIVED per sample: gear = rpm/speed ratio -> nearest gear centroid (log-space);
// thresholds below are the geometric-mean band boundaries. N (0) = stopped/crawling/clutch-in.
// Plotted on the Y axis so gear position is meaningful; read against the ratio panel beside it.
// See infra/vps/grafana/README.md.
from(bucket: "telemetry")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "telemetry" and (r._field == "rpm" or r._field == "speed"))
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> map(fn: (r) => ({ _time: r._time, _value:
      if r.speed < 8.0 or r.rpm < 800.0 then 0.0
      else if r.rpm / r.speed >= 225.6 then 1.0
      else if r.rpm / r.speed >= 156.0 then 2.0
      else if r.rpm / r.speed >= 121.5 then 3.0
      else if r.rpm / r.speed >= 101.6 then 4.0
      else if r.rpm / r.speed >= 87.3 then 5.0
      else 6.0 }))
  |> keep(columns: ["_time", "_value"])
  |> aggregateWindow(every: v.windowPeriod, fn: last, createEmpty: true)

// Trail: every GPS point in the time range. lat/lon are pivoted into one row each
// so the Geomap coords layer reads both. Rows without a fix are dropped by pivot.
from(bucket: "telemetry")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "telemetry" and (r._field == "lat" or r._field == "lon"))
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> keep(columns: ["_time", "lat", "lon"])
